Since the attached PR has not been merged for now, I've found a work-around.

The basic idea is:
1. Declare your meta tags using `data-name` instead of `name`. Example:
  ```jsx
  <meta data-name="citation_author" content="whatever" />
  ```
2. Use a customized `Head` component in `_document.js` that transforms the `data-name` to `name` for these tags when rendering the `html` file. Here's my `_dcument.js`:
  ```jsx
  import Document, { Head, Main } from 'next/document';
  import React from 'react';

  class CustomHead extends Head {
    render() {
      const res = super.render();

      function transform(node) {
        /**
         * Hack to allow multiple meta tags with the same name.
         *
         * This is a hack that transforms meta tags specified as:
         *   <meta data-name="something" ... />
         * to
         *   <meta name="something" ... />
         *
         * This is to avoid next's Head component from removing all
         * instances but one of these tags (needed for citation_author tags).
         *
         * See https://github.com/vercel/next.js/issues/10183
         */
        if (node && node.type === 'meta' && node.props['data-name']) {
          node.props.name = node.props['data-name'];
          delete node.props['data-name'];
        }

        // This ensures that we recurse into child components/arrays
        // in case our metas are nested in fragments/arrays
        if (node && node.props && node.props.children) {
          return {
            ...node,
            props: {
              ...node.props,
              children: Array.isArray(node.props.children)
                ? node.props.children.map(transform)
                : transform(node.props.children),
            },
          };
        }
        if (Array.isArray(node)) {
          return node.map(transform);
        }

        return node;
      }

      return transform(res);
    }
  }

  class FixedDocument extends Document {
    render() {
      return (
        <html lang="en">
          <CustomHead />
          <body>
            <Main className="container" />
          </body>
        </html>
      );
    }
  }

  export default process.env.NODE_ENV === 'production' ? FixedDocument : Document;
```

