Relying on request headers is insecure, you need to use a value you can trust. i.e. serverside provided, not clientside provided. What you do is, you create an environment variable in `next.config.js`, then you use it as a base url:

```js
// next.config.js
module.exports = {
  env: {
    ORIGIN: 'http://localhost:3000/'
  }
}
```

Then in your code

```js
async function fetchFromOrigin (url, options) {
  const origin = typeof window === 'undefined' ? process.env.ORIGIN : '/'
  return fetch(new URL(url, origin), options);
}
```

And in production you supply the origin of your website, or any other host where your webserver can reach itself, ideally it just connects to localhost.

there's the `x-now-deployment-url` request header, it should do the trick for you. Something along the lines of:

```js
function getOrigin (ctx) {
  if (typeof window !== 'undefined') {
    return '/'
  }
  if (ctx.req.headers['x-now-deployment-url']) {
    return `https://${ctx.req.headers['x-now-deployment-url']}`
  }
  return process.env.ORIGIN
}

async function fetchFromOrigin (ctx, url, options) {
  return fetch(new URL(url, getOrigin(ctx)), options)
}
```

