import Head from 'next/head'

export class JsonLd extends React.Component {

  state = {
    data: null
  }

  constructor(props) {
    super(props)

    setTimeout(() => {
      this.setState({ data: { foo: 'bar' } })
    }, 2000)
  }

  render() {
    const { data } = this.state
    if (!data) return ''
    return <Head>
      <script type="application/ld+json">${JSON.stringify(data)}</script>
    </Head>
  }
}
