Here is my approach to reliably accessing query params on initial client-side render. Note that any conditional rendering based on QPs will cause mismatches with server-generated markup.
```tsx
import { useMemo } from 'react';
import { useRouter } from 'next/router';

/**
 * Can't reliably extract QPs from Next's useRouter on initial client-side render.
 * [Issue](https://github.com/vercel/next.js/issues/10521)
 */
export function useQueryParams() {
  const router = useRouter();

  const queryParams = useMemo(() => {
    let pathStr: string | undefined;

    const delimiterIndex = router.asPath.indexOf('?');
    if (delimiterIndex >= 0) {
      pathStr = router.asPath.substring(delimiterIndex);
    }

    return new URLSearchParams(pathStr);
  }, [router.asPath]);

  return queryParams;
}
```

