```ts
import { GetServerSideProps } from 'next'
import { apiResolver } from 'next/dist/next-server/server/api-utils'

export const enrichContext = async (
  context: Parameters<GetServerSideProps>[0],
  middleware?: (req, res, next) => Promise<void>
) => {
  const dummyApiContext = {
    previewModeEncryptionKey: undefined,
    previewModeId: undefined,
    previewModeSigningKey: undefined
  }
  const handler = async (req, res, next) => {
    res.emit('pipe') // This tells the apiResolver that it's ok if the handler doesn't send a response
    if (middleware) await middleware(req, res, next)
  }
  await apiResolver(context.req, context.res, {}, handler, dummyApiContext)
}
``` 

