    const nextBabelLoader = config.module.rules.find(
      (rule) => rule.use?.[1]?.loader === "next-babel-loader"
    );

    if (nextBabelLoader) {
      // Fix for https://github.com/vercel/next.js/issues/12753
      nextBabelLoader.use[1].options.hasReactRefresh = false;
    }

    return config;
  }
}
```

