On the other hand, the `bar` module is not ignored instead because it is passed through `next-transpile-modules` (see the [next.config.js](https://github.com/vercel/next.js/blob/canary/examples/with-yarn-workspaces/packages/web-app/next.config.js#L3) in the example). So just transpile your module (which makes sense, considering that you're in a workspace and you're probably developing your module alongside your next.js app) and get the hot reloading with it.

But what if, for some reason, you'd want the hot reloading of your module but not the transpiling? Well, I've toyed around a little bit and you can actually do it, but you have to override the "ignored" option modified by `next-transpile-modules` itself.

```js
// Here are the modules that need transpiling
const transpiledModules = ['bar'];
// Here are the modules that need hot reloading
const hrModules = transpiledModules.concat(['foo']);

const withTM = require('next-transpile-modules')(transpiledModules)

// This code is shamelessly stolen from next-transpile-modules
// https://github.com/martpie/next-transpile-modules/blob/master/src/next-transpile-modules.js
const PATH_DELIMITER = '[\\\\/]'; // match 2 antislashes or one slash
const safePath = (module) => module.split(/[\\\/]/g).join(PATH_DELIMITER);
const generateExcludes = (modules) => {
  return [
    new RegExp(
      `node_modules${PATH_DELIMITER}(?!(${modules.map(safePath).join('|')})(${PATH_DELIMITER}|$)(?!.*node_modules))`
    )
  ];
};
const regexEqual = (x, y) => {
  return (
    x instanceof RegExp &&
    y instanceof RegExp &&
    x.source === y.source &&
    x.global === y.global &&
    x.ignoreCase === y.ignoreCase &&
    x.multiline === y.multiline
  );
};

// Get the regex generated by next-transpile-modules
const oldRegex = generateExcludes(transpiledModules)[0]
// And create our own regex 
const excludes = generateExcludes(hrModules);

// Remove the regex added by next-transpile-modules (that has only bar)
// and add our own which includes foo
module.exports = withTM({
  webpackDevMiddleware: (config) => {
    const ignored = config.watchOptions.ignored
      .filter((regexp) => !regexEqual(regexp, oldRegex)
      .concat(excludes);

    config.watchOptions.ignored = ignored;

    return config;
  }
});
```

